async def get(path):
    return fetch_text('{BASE}' + path)
print(gather(get('/text'), get('/text'), get('/text')))

sock = ws_open('{WS_BASE}/ws', 'echo')
got = None
while True:
    ev = receive()
    if '"type":"open"' in ev:
        ws_send(sock, 'hello')
    elif '"type":"message"' in ev:
        got = 'hello' in ev
        ws_close(sock)
    elif '"type":"close"' in ev:
        break
print(got)
